arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" --data "token=<TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d); sys.exit(0)
for u in d['members']:
    if u.get('is_owner'):
        print('OWNER:', u['id'], u['profile'].get('real_name'), u['profile'].get('display_name'))
print('total users:', len(d['members']))
"

